package org.humanjourney.core.mapfeature;
import java.util.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.network.chat.Component;
import org.humanjourney.core.geography.*;
/** Independent proximity discovery and derived discovered-only transport. No geography-context writes. */
public final class FeatureServer {
 private record Input(int entity,String dimension,double x,double z,GeographyRoles role,long catalog){}
 private record Key(long discovery,long catalog){}
 private static final class Peer{int entity,requestTick=Integer.MIN_VALUE;long sequence;Key key;Map<String,MapFeature.View> view=Map.of();boolean force=true,warned;}
 private static MinecraftServer owner;private static UUID session=UUID.randomUUID();private static long sequence;private static Key projectedKey;private static Map<String,MapFeature.View> projected=Map.of();
 private static final Map<UUID,Input> evaluations=new HashMap<>();private static final Map<UUID,Peer> peers=new HashMap<>();
 public static void clear(){owner=null;session=UUID.randomUUID();sequence=0;evaluations.clear();peers.clear();projectedKey=null;projected=Map.of();}
 private static void owner(MinecraftServer server){if(owner!=server){clear();owner=server;}}
 public static void tick(MinecraftServer server){owner(server);if(server.getTickCount()%10!=0)return;var data=FeatureCatalog.state();var saved=SavedFeatures.get(server);var online=server.getPlayerList().getPlayers();var ids=new HashSet<UUID>();var added=new TreeSet<String>();for(var p:online){ids.add(p.getUUID());var role=GeographyServer.roles(p);var input=new Input(p.getId(),p.level().dimension().location().toString(),p.getX(),p.getZ(),role,data.revision());if(!input.equals(evaluations.put(p.getUUID(),input))&&role.canDiscover())added.addAll(saved.discover(role,data.data(),input.dimension(),input.x(),input.z()));}evaluations.keySet().retainAll(ids);if(!added.isEmpty()){var labels=added.stream().limit(4).map(id->data.data().features().get(id).view().label()).toList();String text="[Human Journey] Discovered: "+String.join(", ",labels)+(added.size()>4?" (+"+(added.size()-4)+" more)":"");for(var p:online)if(GeographyServer.roles(p).participant())p.sendSystemMessage(Component.literal(text));}sync(server);}
 private static boolean send(ServerPlayer player,List<FeaturePackets.Frame> frames,Peer peer){for(var frame:frames)if(!FeatureNetwork.send(frame,player)){peer.force=true;if(!peer.warned){peer.warned=true;com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] Map feature sync failed for {}; full retry scheduled",player.getScoreboardName());}return false;}peer.warned=false;return true;}
 public static void sync(MinecraftServer server){owner(server);var saved=SavedFeatures.get(server).snapshot();var catalog=FeatureCatalog.state();var key=new Key(saved.revision(),catalog.revision());if(!key.equals(projectedKey)){projected=FeatureCatalog.project(catalog.data(),saved.ids());projectedKey=key;}var online=server.getPlayerList().getPlayers();var ids=new HashSet<UUID>();for(var p:online){ids.add(p.getUUID());var peer=peers.get(p.getUUID());if(!GeographyServer.roles(p).participant()){if(peer!=null){var h=new FeaturePackets.Header(session,++sequence,saved.revision(),catalog.revision());if(send(p,FeaturePackets.frames(h,FeaturePackets.Mode.CLEAR,0,List.of(),List.of()),peer))peers.remove(p.getUUID());}continue;}peer=peers.computeIfAbsent(p.getUUID(),id->new Peer());if(!peer.force&&peer.entity==p.getId()&&key.equals(peer.key))continue;boolean full=peer.force||peer.key==null||peer.entity!=p.getId()||peer.key.catalog()!=key.catalog();var mode=saved.ids().isEmpty()?FeaturePackets.Mode.CLEAR:full?FeaturePackets.Mode.FULL:FeaturePackets.Mode.DELTA;var updates=new ArrayList<MapFeature.View>();var removed=new ArrayList<String>();if(mode==FeaturePackets.Mode.FULL)updates.addAll(projected.values());else if(mode==FeaturePackets.Mode.DELTA){for(var e:projected.entrySet())if(!e.getValue().equals(peer.view.get(e.getKey())))updates.add(e.getValue());for(String old:peer.view.keySet())if(!projected.containsKey(old))removed.add(old);}var header=new FeaturePackets.Header(session,++sequence,saved.revision(),catalog.revision());if(send(p,FeaturePackets.frames(header,mode,mode==FeaturePackets.Mode.DELTA?peer.sequence:0,updates,removed),peer)){peer.force=false;peer.key=key;peer.view=projected;peer.entity=p.getId();peer.sequence=header.sequence();}}peers.keySet().retainAll(ids);}
 public static void request(ServerPlayer p){if(!GeographyServer.roles(p).participant())return;var server=p.level().getServer();if(server==null)return;owner(server);var peer=peers.computeIfAbsent(p.getUUID(),id->new Peer());int now=server.getTickCount();if(peer.requestTick!=Integer.MIN_VALUE&&now>=peer.requestTick&&now-peer.requestTick<60)return;peer.requestTick=now;peer.force=true;}
 public static String describe(MinecraftServer server){var s=FeatureCatalog.state();var d=SavedFeatures.get(server).snapshot();var counts=new TreeMap<String,Long>();for(var type:MapFeature.Type.values())counts.put(type.name().toLowerCase(Locale.ROOT),s.data().features().values().stream().filter(f->f.view().type()==type).count());long stale=d.ids().stream().filter(id->!s.data().features().containsKey(id)).count();return "Map features: loaded="+s.data().features().size()+" types="+counts+" discovered="+d.ids().size()+" stale="+stale+" staleIDs="+d.ids().stream().filter(id->!s.data().features().containsKey(id)).sorted().limit(8).toList()+(stale>8?" (+"+(stale-8)+" more)":"")+" catalog="+s.revision()+" discovery="+d.revision()+" last successful reload="+s.lastSuccess()+" error="+s.error()+"\n"+FeatureCatalog.complexity(s.data());}
 private FeatureServer(){}
}
